const intf=new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0,useGrouping:true});
const integer=n=>intf.format(Math.round(Number(n)||0));
const format=integer;
const duration=ms=>{const t=Math.max(0,Math.floor((ms||0)/1000));return [Math.floor(t/3600),Math.floor(t/60)%60,t%60].map(x=>String(x).padStart(2,'0')).join(':');};
const rate=(value,ms)=>ms>0?value*3600000/Math.max(ms,60000):0;
const timeAgo=ms=>{if(ms===null||ms===undefined)return 'sem atividade';const s=Math.max(0,Math.floor(ms/1000));if(s<10)return 'agora';if(s<60)return `há ${s}s`;const m=Math.floor(s/60);if(m<60)return `há ${m} min`;const h=Math.floor(m/60);return `há ${h}h`;};
const dateTime=at=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(at));
let current=null,selected='all',trendData=[],events=[],sessions={active:[],archived:[]},lastExtras=0,extrasBusy=false;
