function notify(text){const el=$('notice');if(!el)return;clearTimeout(notify.timer);el.textContent=String(text||'');el.hidden=!text;if(text)notify.timer=setTimeout(()=>{el.hidden=true;},12000);}

async function action(fn){try{return await fn();}catch(error){console.error(error);const detail=String(error?.message||error||'erro desconhecido');notify(`Não foi possível concluir a ação: ${detail}`);return null;}}
function currentRecord(){return selected==='all'?null:current?.rows?.[Number(selected)]?.record||null;}
function selectedValues(){return selected==='all'?current?.total?.values:currentRecord()?.values;}
function selectedMs(){return selected==='all'?current?.total?.ms:currentRecord()?.ms;}
function renderRemote(data){
  const badge=$('remoteBadge'),remote=data.remote||{};
  if(!remote.enabled){badge.textContent='Remoto desligado';badge.className='pill secondary';}
  else if(remote.lastSuccess&&Date.now()-remote.lastSuccess<45000){badge.textContent='● Remoto online';badge.className='pill';}
  else if(remote.lastError){badge.textContent='Remoto com erro';badge.className='pill error';}
  else{badge.textContent='Remoto aguardando';badge.className='pill warn';}
  $('remoteEnabled').checked=!!data.settings.remote.enabled;
  const endpointInput=$('remoteEndpoint');
  if(document.activeElement!==endpointInput)endpointInput.value=data.settings.remote.endpoint||'';
  const tokenInput=$('remoteToken');
  const tokenConfigured=!!data.settings.remote.tokenConfigured;
  tokenInput.placeholder=tokenConfigured?'Chave salva ✓ · cole novamente só para trocar':'Cole a chave privada do Render';
  const token=tokenConfigured?'token configurado':'token não configurado';
  $('remoteStatus').textContent=remote.lastError?`Erro: ${remote.lastError}`:remote.lastSuccess?`Último envio ${timeAgo(Date.now()-remote.lastSuccess)} · ${token}`:`${token}. O primeiro envio acontece com o Grid coletando.`;
  const code=String(remote.pairCode||'').replace(/\D/g,'');$('pairCode').textContent=code.length===6?`${code.slice(0,3)} ${code.slice(3)}`:'— — — — — —';
  const left=Math.max(0,(Number(remote.pairExpiresAt)||0)-Date.now());$('pairCountdown').textContent=left>0?`Expira em ${Math.ceil(left/60000)} min · funciona uma vez.`:'Gere um código e digite os 6 números no celular.';
}
function renderServer(data){
  const s=data.server||{},status=s.status||'unknown',badge=$('serverBadge'),card=$('serverCard');let title='Servidor: verificando',detail='Aguardando resposta das contas.';
  badge.className='pill warn';card.className='server-card';
  if(status==='online'){title='● Servidor online';detail='As sessões estão respondendo normalmente.';badge.className='pill';card.classList.add('online');}
  else if(status==='offline'){title='Servidor offline';detail=`Queda/reinício detectado${s.retries?` · ${s.retries} tentativa(s) de reconexão`:''}.`;badge.className='pill error';card.classList.add('offline');}
  else if(status==='recovering'){title='Reconectando…';detail=`O servidor está sendo testado novamente · tentativa ${s.retries||1}.`;badge.className='pill warn';card.classList.add('recovering');}
  else if(status==='degraded'){title='Instabilidade';detail='Uma ou mais sessões tiveram falha. O Grid está verificando se é uma queda geral.';badge.className='pill warn';card.classList.add('recovering');}
  const notice=data.rows?.map(r=>r.record?.live?.serverNotice).find(Boolean);if(notice&&status==='online')detail='Aviso detectado no jogo: '+notice;
  badge.textContent=title;$('serverCardTitle').textContent=title.replace(/^●\s*/,'');$('serverCardDetail').textContent=detail+(s.lastReason?` · ${s.lastReason}`:'');
}
