  const ranked=data.rows.map((x,i)=>({x,i,rate:rates[i]})).sort((a,b)=>{if(!!a.x.record!==!!b.x.record)return a.x.record?-1:1;return b.rate-a.rate;});
  const comp=$('accountComparison');if(!comp)return;comp.replaceChildren();
  ranked.forEach((entry,rank)=>{
    const {x,i}=entry,line=document.createElement('div');line.className='comparison-row';const dot=document.createElement('span');dot.className='account-dot a'+i;const labels=document.createElement('div');labels.className='labels';const name=document.createElement('b');const badge=['🥇','🥈','🥉','4º'][rank]||`${rank+1}º`;name.textContent=`${badge} · ${x.record?.nick||'Aguardando login'}`;const small=document.createElement('small');small.textContent=`Conta ${i+1} · ${x.status}`;const track=document.createElement('div');track.className='track';const bar=document.createElement('i');bar.style.width=(entry.rate/max*100)+'%';track.append(bar);labels.append(name,small,track);const n=document.createElement('strong');n.textContent=x.record?format(entry.rate):'—';line.append(dot,labels,n);comp.append(line);
  });
