function renderAutoInspector(status){const badge=document.getElementById('alphaAutoInspectorBadge');if(!badge)return;const x=status||{},age=x.lastAt?Math.max(0,Math.round((Date.now()-Number(x.lastAt))/1000)):null,usable=Number(x.usableListings||0),rx=Number(x.marketRx||0),sock=Number(x.socketReady||0),target=Math.max(1,Number(x.targetCount||1)),slots=(x.activeSlots||[]).map(Number).filter(Number.isInteger),slotLabel=slots.length?slots.map(v=>'C'+(v+1)).join('+'):'—',catalog=x.catalog||{};if(x.lastError){badge.textContent='INSPEÇÃO AUTO: ERRO';badge.classList.add('warning');badge.title=x.lastError;}else if(x.running){badge.textContent='INSPEÇÃO GLOBAL: '+slotLabel+' LENDO…';badge.classList.remove('warning');}else if(usable>0){badge.textContent='INSPEÇÃO GLOBAL: '+slotLabel+' · '+usable+' operáveis';badge.classList.remove('warning');}else{badge.textContent='INSPEÇÃO GLOBAL: '+slotLabel+' AGUARDANDO';badge.classList.add('warning');}badge.title=(age===null?'Aguardando primeira leitura':('Última leitura há '+age+'s'))+' · rede '+Number(x.networkAttached||0)+'/'+target+' · socket '+sock+'/'+target+' · RX '+rx+' · categorias '+Number(catalog.categories||0)+' · itens '+Number(catalog.items||0)+' · espécies '+Number(catalog.species||0);const out=document.getElementById('marketScanOutput');if(out&&!lastMarketScanText){const nl=String.fromCharCode(10),state=usable>0?'PRONTO PARA O AUTO TRADER':rx>0?'MARKET RESPONDEU, MAS SEM ANÚNCIOS DETALHADOS':'AGUARDANDO FEED REAL DO MARKET',concurrency=Math.max(1,Number(x.concurrency||target));out.textContent='SCANNER GLOBAL DO MARKET · '+state+nl+'Contas ativas: '+slotLabel+' · '+concurrency+' simultânea(s)'+nl+'Rotação: '+(concurrency>=4?'desativada (4/4 trabalhando)':'aproximadamente 60s')+nl+'Categorias aprendidas: '+Number(catalog.categories||0)+nl+'Itens catalogados: '+Number(catalog.items||0)+nl+'Espécies Pokémon catalogadas: '+Number(catalog.species||0)+nl+'Última leitura: '+(x.lastAt?new Date(Number(x.lastAt)).toLocaleTimeString('pt-BR'):'aguardando')+nl+'Captura focada: '+Number(x.networkAttached||0)+'/'+target+nl+'Socket pronto: '+sock+'/'+target+nl+'Market enviado/recebido: '+Number(x.marketTx||0)+' / '+rx+nl+'Anúncios detalhados: '+Number(x.listingRows||0)+nl+'Anúncios operáveis agora: '+usable+nl+'Cross-market: '+Number(x.crossMarket||0)+(x.probeError?nl+'Probe: '+x.probeError:'')+nl+nl+'Alpha 9.7: scanner global de itens + Pokémon · concorrência configurável 1–4 contas.';}}

