 const box=$('proMoney');if(!box||!window.GridiumProfessional)return;const m=window.GridiumProfessional.dashboardModel(state,alphaCurrency),money=x=>integer(x||0)+' '+(alphaCurrency==='gems'?'Gems':'Coins');
 $('proHeadline').textContent=m.title;
